package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

const (
	defaultStyle = "stars"
	sepCh        = "\t"
	hasAlign     = true
	hasPad       = true
	hasMax       = false
	hasRules     = false
	hasN         = false
)

var styles = map[string][4]string{"stars": {".", "~", ":", "~"}, "plain": {"+", "=", "I", "="}, "thin": {".", "=", ":", "#"}}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func isNum(s string) bool {
	body := s
	if strings.HasPrefix(s, "+") || strings.HasPrefix(s, "-") {
		body = s[1:]
	}
	if i := strings.IndexByte(body, '.'); i >= 0 {
		return isDigits(body[:i]) && isDigits(body[i+1:])
	}
	return isDigits(body)
}

func main() {
	os.Exit(run())
}

func run() int {
	opts := map[string]string{"style": defaultStyle, "header": "yes", "pad": "1", "rules": "edges", "align": "", "max": ""}
	offered := map[string]bool{"style": true, "header": true, "align": hasAlign, "pad": hasPad, "max": hasMax, "rules": hasRules}
	seen := map[string]bool{}
	for _, a := range os.Args[1:] {
		i := strings.IndexByte(a, '=')
		if i < 0 {
			return 2
		}
		k, v := a[:i], a[i+1:]
		if !offered[k] || seen[k] {
			return 2
		}
		seen[k] = true
		switch k {
		case "style":
			if _, ok := styles[v]; !ok {
				return 2
			}
		case "header":
			if v != "yes" && v != "no" {
				return 2
			}
		case "rules":
			if v != "edges" && v != "all" {
				return 2
			}
		case "pad":
			if v != "0" && v != "1" && v != "2" && v != "3" {
				return 2
			}
		case "max":
			n, _ := strconv.Atoi(v)
			if len(v) < 1 || len(v) > 2 || !isDigits(v) || n < 2 {
				return 2
			}
		case "align":
			allowed := "lrc"
			if hasN {
				allowed = "lrcn"
			}
			if v == "" || strings.Trim(v, allowed) != "" {
				return 2
			}
		}
		opts[k] = v
	}
	raw, _ := io.ReadAll(os.Stdin)
	data := strings.TrimSuffix(string(raw), "\n")
	if len(raw) > 0 && raw[len(raw)-1] != '\n' {
		data = string(raw)
	}
	if data == "" {
		return 1
	}
	var rows [][]string
	for _, line := range strings.Split(data, "\n") {
		rows = append(rows, strings.Split(line, sepCh))
	}
	if opts["max"] != "" {
		m, _ := strconv.Atoi(opts["max"])
		for _, r := range rows {
			for j, c := range r {
				if len(c) > m {
					r[j] = c[:m-1] + "~"
				}
			}
		}
	}
	nc := 0
	for _, r := range rows {
		if len(r) > nc {
			nc = len(r)
		}
	}
	for i, r := range rows {
		for len(r) < nc {
			r = append(r, "")
		}
		rows[i] = r
	}
	widths := make([]int, nc)
	for _, r := range rows {
		for j, c := range r {
			if len(c) > widths[j] {
				widths[j] = len(c)
			}
		}
	}
	st := styles[opts["style"]]
	corner, h, v, hh := st[0], st[1], st[2], st[3]
	pad, _ := strconv.Atoi(opts["pad"])
	al := opts["align"]
	place := func(cell string, j int) string {
		a := byte('l')
		if j < len(al) {
			a = al[j]
		}
		if a == 'n' {
			if isNum(cell) {
				a = 'r'
			} else {
				a = 'l'
			}
		}
		room := widths[j] - len(cell)
		switch a {
		case 'l':
			return cell + strings.Repeat(" ", room)
		case 'r':
			return strings.Repeat(" ", room) + cell
		}
		return strings.Repeat(" ", room/2) + cell + strings.Repeat(" ", room-room/2)
	}
	rule := func(ch string) string {
		parts := make([]string, nc)
		for j, w := range widths {
			parts[j] = strings.Repeat(ch, w+2*pad)
		}
		return corner + strings.Join(parts, corner) + corner
	}
	var out []string
	out = append(out, rule(h))
	header := opts["header"] == "yes"
	sp := strings.Repeat(" ", pad)
	for i, r := range rows {
		parts := make([]string, nc)
		for j, c := range r {
			parts[j] = sp + place(c, j) + sp
		}
		out = append(out, v+strings.Join(parts, v)+v)
		if i == 0 && header {
			out = append(out, rule(hh))
		} else if i < len(rows)-1 && opts["rules"] == "all" {
			out = append(out, rule(h))
		}
	}
	out = append(out, rule(h))
	fmt.Print(strings.Join(out, "\n") + "\n")
	return 0
}

